337	// Submit 校验并接收一笔交易进入交易池。
338	// 拒绝时返回 *RejectError，可通过其 Reason 取得具体原因。
339	//
340	// 现有校验与拒绝原因优先于容量判断。同发送者同序号的合法加费替换不增加计数，
341	// 满池也可执行且不淘汰其他交易。全新交易在池满时只能从未被任何未决候选引用的
342	// 排队交易中挤出费用最低（同费取标识字典序最大）的一笔，且仅当新交易费用更高、
343	// 或费用相同且标识更小时成功；否则以 ReasonPoolFull 拒绝，池状态不变、不留历史。
344	func (n *Node) Submit(tx *Transaction) (*SubmitResult, error) {
345		if tx == nil {
346			return nil, errors.New("nil transaction")
347		}
348		n.mu.Lock()
349		defer n.mu.Unlock()
350	
351		cur := n.st
352		if tx.Sequence == 0 {
353			return nil, reject("sequence-must-be-positive", "sequence must be a positive integer")
354		}
355		if !tx.Verify() {
356			return nil, reject(ReasonBadSignature, "signature verification failed for sender %x", tx.Sender)
357		}
358		id := tx.ID()
359		// 同一标识的交易再次提交，一律视为重复（即使此前已确认、被替换、过期或被挤出）。
360		if _, ok := cur.Entries[id]; ok {
361			return nil, reject(ReasonDuplicate, "transaction %s already exists", id)
362		}
363		if cur.Round >= tx.Expiry {
364			return nil, reject(ReasonExpired, "expiry round %d is not greater than current round %d", tx.Expiry, cur.Round)
365		}
366		sender := tx.SenderHex()
367		if confirmed := cur.Accounts[sender]; tx.Sequence <= confirmed {
368			return nil, reject(ReasonOldSequence, "sequence %d is not greater than confirmed sequence %d", tx.Sequence, confirmed)
369		}
370		seqs := cur.Pool[sender]
371		isReplace := false
372		if seqs != nil {
373			if oldID, ok := seqs[tx.Sequence]; ok {
374				isReplace = true
375				old := cur.Entries[oldID]
376				if old.Status == stProposed {
377					return nil, reject(ReasonProposalLocked, "sequence %d is referenced by a pending candidate and cannot be replaced", tx.Sequence)
378				}
379				if tx.Fee <= old.Tx.Fee {
380					return nil, reject(ReasonLowFee, "new fee %d is not strictly higher than existing fee %d", tx.Fee, old.Tx.Fee)
381				}
382			}
383		}
384	
385		// 容量判断位于全部现有校验之后，且只针对新占位置的交易。
386		var evictID string
387		if !isReplace && cur.Capacity > 0 && cur.poolSize() >= cur.Capacity {
388			victim, ok := cur.evictionVictim()
389			if !ok {
390				return nil, reject(ReasonPoolFull,
391					"pool is full (%d/%d transactions) and no queued transaction is evictable", cur.poolSize(), cur.Capacity)
392			}
393			ve := cur.Entries[victim]
394			// 新交易必须严格优于当前优先级最低的可淘汰交易才接收：
395			// 费用更高，或费用相同且新标识字典序更小。
396			if !higherPriority(tx.Fee, id, ve.Tx.Fee, victim) {
397				return nil, reject(ReasonPoolFull,
398					"pool is full (%d/%d transactions): new transaction (fee %d) does not beat evictable transaction %s (fee %d)",
399					cur.poolSize(), cur.Capacity, tx.Fee, victim, ve.Tx.Fee)
400			}
401			evictID = victim
402		}
403	
404		// 校验通过后在副本上修改，落盘成功才替换内存，失败时确认前状态保持不变。
405		st := cur.clone()
406		result := &SubmitResult{TxID: id}
407		if oldID, ok := st.Pool[sender][tx.Sequence]; ok {
408			old := st.Entries[oldID]
409			old.Status = stReplaced
410			old.ReplacedBy = id
411			result.ReplacedID = oldID
412		} else if evictID != "" {
413			// 接收新交易与淘汰旧交易在同一个副本上一起生效、一起落盘。
414			v := st.Entries[evictID]
415			v.Status = stDropped
416			v.DropReason = DropReasonPoolCapacity
417			v.DropRound = st.Round
418			vsender := v.Tx.SenderHex()
419			delete(st.Pool[vsender], v.Tx.Sequence)
420			if len(st.Pool[vsender]) == 0 {
421				delete(st.Pool, vsender)
422			}
423			result.EvictedID = evictID
424		}
425	
426		txCopy := *tx
427		txCopy.Sender = append([]byte(nil), tx.Sender...)
428		txCopy.Content = append([]byte(nil), tx.Content...)
429		txCopy.Signature = append([]byte(nil), tx.Signature...)
430		st.Entries[id] = &poolEntry{Tx: &txCopy, Status: stQueued}
431		if st.Pool[sender] == nil {
432			st.Pool[sender] = map[uint64]string{}
433		}
434		st.Pool[sender][tx.Sequence] = id
435	
436		if err := n.save(st); err != nil {
437			return nil, err
438		}
439		n.st = st
440		return result, nil
441	}
442	
443	// higherPriority 是交易优先级的唯一比较规则：费用更高者优先；
444	// 费用相同，交易标识按字典序更小者优先。费用按无符号 64 位整数直接比较，
445	// 0 与最大值也能正确区分高低，相差很大的两笔费用不会反转或被判为相同；
446	// 同费时以完整交易标识的字典序为准。
447	// 打包选优、满池找可淘汰交易、判断新交易是否值得接收都通过它表达高低关系。
448	func higherPriority(feeA uint64, idA string, feeB uint64, idB string) bool {
449		return feeA > feeB || (feeA == feeB && idA < idB)
450	}
451	
452	// poolSize 返回当前占位的交易数：排队与等待投票（被未决候选引用）的交易。
453	// 同一交易被多个候选引用只算一笔；已确认、被替换、已过期与被挤出的历史不占位置。
454	func (s *state) poolSize() uint64 {
455		var n uint64
456		for _, seqs := range s.Pool {
457			n += uint64(len(seqs))
458		}
459		return n
460	}
461	
462	// evictionVictim 选出满池时唯一可被淘汰的交易：未被任何未决候选引用的排队
463	// 交易中优先级最低者（费用最低，费用相同取交易标识字典序最大者）。
464	// 选择只取决于费用与标识，与遍历顺序无关，结果确定。无可淘汰交易时第二个返回值为 false。
465	func (s *state) evictionVictim() (string, bool) {
466		var victim string
467		var victimFee uint64
468		found := false
469		for _, seqs := range s.Pool {
470			for _, id := range seqs {
471				e := s.Entries[id]
472				if e.Status != stQueued {
473					continue // 被未决候选引用的交易受保护
474				}
475				// 候选比当前受害者优先级更低（即受害者更高）时，改选候选。
476				if !found || higherPriority(victimFee, victim, e.Tx.Fee, id) {
477					victim, victimFee, found = id, e.Tx.Fee, true
478				}
479			}
480		}
481		return victim, found
482	}
483	
484	// 额外拒绝原因。
485	const (
486		// ReasonProposalLocked 同发送者同序号交易已被未决候选引用，禁止替换。
487		ReasonProposalLocked = "tx-in-proposal"
488		// ReasonUnknownTx 查询的交易标识不存在。
489		ReasonUnknownTx = "unknown-transaction"
490		// ReasonUnknownBlock 查询的区块高度不存在。
491		ReasonUnknownBlock = "unknown-block"
492		// ReasonTxNotInPool 候选引用了已退出交易池的交易（已确认、被替换、已过期或被挤出）。
493		ReasonTxNotInPool = "tx-not-in-pool"
494		// ReasonDuplicateInList 候选列表中同一交易出现多次。
495		ReasonDuplicateInList = "duplicate-in-list"
496		// ReasonTooManyTxs 候选包含的交易超过单块上限。
497		ReasonTooManyTxs = "too-many-transactions"
498		// ReasonSequenceGap 候选中某账户的序号未从已确认序号加一开始连续递增。
499		ReasonSequenceGap = "sequence-not-consecutive"
500	)
